svg.script:

(function() {
  const tickX = [170, 227.5, 285, 342.5, 400, 457.5, 515, 572.5, 630];
  const states = [
    {
      title: "Envelhecimento Saudável",
      scale: "Estágio 0/8 • Caso Clínico",
      lawton: "8/8",
      katz: "6/6",
      lColor: "var(--c-green)",
      kColor: "var(--c-green)",
      lBg: "rgba(52, 199, 89, 0.1)",
      kBg: "rgba(52, 199, 89, 0.1)",
      lines: [
        "Dona Maria, 76 anos: Vive totalmente só,",
        "cozinha, faz compras no mercado municipal,",
        "gerencia sua aposentadoria e usa o",
        "WhatsApp diariamente para falar com a família."
      ],
      rec: "Conduta: Estimular estilo de vida ativo e preventivo."
    },
    {
      title: "Perda Funcional Inicial (AIVD 1)",
      scale: "Estágio 1/8 • Caso Clínico",
      lawton: "6/8",
      katz: "6/6",
      lColor: "var(--c-amber)",
      kColor: "var(--c-green)",
      lBg: "rgba(255, 149, 0, 0.1)",
      kBg: "rgba(52, 199, 89, 0.1)",
      lines: [
        "Sr. José, 80 anos: Esqueceu de pagar a conta",
        "de luz duas vezes e errou o troco na padaria.",
        "A filha assumiu a administração das contas.",
        "As outras atividades instrumentais seguem preservadas."
      ],
      rec: "Conduta: Investigar déficit cognitivo leve (DCL)."
    },
    {
      title: "Declínio Instrumental (AIVD 2)",
      scale: "Estágio 2/8 • Caso Clínico",
      lawton: "4/8",
      katz: "6/6",
      lColor: "var(--c-amber)",
      kColor: "var(--c-green)",
      lBg: "rgba(255, 149, 0, 0.1)",
      kBg: "rgba(52, 199, 89, 0.1)",
      lines: [
        "Dona Alzira, 82 anos: Fica confusa no mercado",
        "e não consegue carregar sacolas. Necessita",
        "de auxílio direto para realizar compras,",
        "embora realize tarefas menores em casa."
      ],
      rec: "Conduta: Reabilitação cognitiva e supervisão."
    },
    {
      title: "Declínio Instrumental (AIVD 3)",
      scale: "Estágio 3/8 • Caso Clínico",
      lawton: "2/8",
      katz: "6/6",
      lColor: "var(--c-amber)",
      kColor: "var(--c-green)",
      lBg: "rgba(255, 149, 0, 0.1)",
      kBg: "rgba(52, 199, 89, 0.1)",
      lines: [
        "Sr. Antônio, 85 anos: Esqueceu a panela no",
        "fogo, queimando o alimento e gerando risco",
        "de incêndio. Foi proibido de cozinhar",
        "pela família. Mantém autocuidado básico."
      ],
      rec: "Conduta: Adaptação ambiental para segurança física."
    },
    {
      title: "Perda Total de AIVDs (AIVD 4)",
      scale: "Estágio 4/8 • Caso Clínico",
      lawton: "0/8",
      katz: "6/6",
      lColor: "var(--c-red)",
      kColor: "var(--c-green)",
      lBg: "rgba(255, 59, 48, 0.1)",
      kBg: "rgba(52, 199, 89, 0.1)",
      lines: [
        "Dona Clarice, 88 anos: Perda instrumental",
        "completa. Não consegue discar ou usar o",
        "telefone. Dependência total de terceiros para",
        "todas as atividades de integração social."
      ],
      rec: "Conduta: Apoio permanente de cuidador para AIVDs."
    },
    {
      title: "Início da Perda de ABVDs (ABVD 1)",
      scale: "Estágio 5/8 • Caso Clínico",
      lawton: "0/8",
      katz: "5/6",
      lColor: "var(--c-red)",
      kColor: "var(--c-red)",
      lBg: "rgba(255, 59, 48, 0.1)",
      kBg: "rgba(255, 59, 48, 0.1)",
      lines: [
        "Sr. Geraldo, 90 anos: Veste casaco ao avesso",
        "e erra os botões da camisa. Passou a exigir",
        "ajuda física direta para se vestir pela manhã.",
        "Primeiro degrau de autocuidado comprometido."
      ],
      rec: "Conduta: Auxílio diário nas ABVDs de vestir."
    },
    {
      title: "Declínio Básico Moderado (ABVD 2)",
      scale: "Estágio 6/8 • Caso Clínico",
      lawton: "0/8",
      katz: "4/6",
      lColor: "var(--c-red)",
      kColor: "var(--c-red)",
      lBg: "rgba(255, 59, 48, 0.1)",
      kBg: "rgba(255, 59, 48, 0.1)",
      lines: [
        "Dona Rita, 92 anos: Apresenta forte",
        "instabilidade de marcha. Exige ajuda física",
        "direta para entrar no box, ensaboar-se",
        "e secar-se com segurança no chuveiro."
      ],
      rec: "Conduta: Instalar barras de apoio e supervisão de banho."
    },
    {
      title: "Declínio Básico Avançado (ABVD 3)",
      scale: "Estágio 7/8 • Caso Clínico",
      lawton: "0/8",
      katz: "2/6",
      lColor: "var(--c-red)",
      kColor: "var(--c-red)",
      lBg: "rgba(255, 59, 48, 0.1)",
      kBg: "rgba(255, 59, 48, 0.1)",
      lines: [
        "Sr. Manoel, 94 anos: Apresenta incontinência",
        "urinária estabelecida com perda do controle",
        "esfincteriano. Necessita do uso de fraldas",
        "descartáveis e auxílio constante para higiene."
      ],
      rec: "Conduta: Cuidados de pele (prevenção de dermatite)."
    },
    {
      title: "Dependência Funcional Total (ABVD 4)",
      scale: "Estágio 8/8 • Caso Clínico",
      lawton: "0/8",
      katz: "0/6",
      lColor: "var(--c-red)",
      kColor: "var(--c-red)",
      lBg: "rgba(255, 59, 48, 0.1)",
      kBg: "rgba(255, 59, 48, 0.1)",
      lines: [
        "Dona Francisca, 96 anos: Restrita ao leito.",
        "Não consegue mais levar o alimento à boca.",
        "Dependência funcional total (Katz 0/6) para",
        "todas as funções de sobrevivência elementar."
      ],
      rec: "Conduta: Nutrição assistida, conforto e paliativos."
    }
  ];

  const steps = [
    {
      id: 1,
      title: "Gestão Financeira (AIVD 1)",
      scale: "Escala de Lawton-Brody",
      lines: [
        "Capacidade de cuidar das próprias finanças, pagar",
        "contas em dia, ir ao banco e gerenciar recursos.",
        "Requer alto funcionamento executivo, memória,",
        "atenção e cálculo. Primeira perda na demência."
      ],
      rec: "Impacto: Perda precoce da autonomia financeira."
    },
    {
      id: 2,
      title: "Fazer Compras (AIVD 2)",
      scale: "Escala de Lawton-Brody",
      lines: [
        "Planejar compras, escolher itens adequados,",
        "realizar o pagamento e transportar sacolas.",
        "Envolve funções cognitivas complexas,",
        "mobilidade física e força muscular."
      ],
      rec: "Impacto: Necessidade de ajuda externa instrumental."
    },
    {
      id: 3,
      title: "Preparar Refeições (AIVD 3)",
      scale: "Escala de Lawton-Brody",
      lines: [
        "Planejar, cozinhar e servir uma refeição.",
        "Exige sequenciamento lógico de passos,",
        "manuseio seguro de fogo, gás e cortantes.",
        "Sua perda eleva o risco de acidentes domésticos."
      ],
      rec: "Impacto: Risco de queimaduras e incêndios."
    },
    {
      id: 4,
      title: "Usar o Telefone (AIVD 4)",
      scale: "Escala de Lawton-Brody",
      lines: [
        "Buscar contatos, discar números, receber",
        "chamadas e manter comunicação compreensível.",
        "A perda reflete declínio da socialização,",
        "da destreza manual e da cognição imediata."
      ],
      rec: "Impacto: Isolamento social e perda de rede de apoio."
    },
    {
      id: 5,
      title: "Vestir-se (ABVD 1)",
      scale: "Escala de Katz",
      lines: [
        "Escolher roupas apropriadas, abotoar,",
        "fechar zíperes, vestir e calçar sapatos.",
        "Exige planejamento motor (praxia), flexibilidade,",
        "equilíbrio e coordenação fina e grossa."
      ],
      rec: "Impacto: Início da perda de independência básica."
    },
    {
      id: 6,
      title: "Banhar-se (ABVD 2)",
      scale: "Escala de Katz",
      lines: [
        "Lavar-se por completo, entrar e sair da",
        "banheira/box de forma segura.",
        "Exige equilíbrio dinâmico, força e flexibilidade.",
        "A perda está ligada a quedas no banheiro."
      ],
      rec: "Impacto: Necessidade de supervisão ou auxílio físico."
    },
    {
      id: 7,
      title: "Continência (ABVD 3)",
      scale: "Escala de Katz",
      lines: [
        "Controle esfincteriano voluntário da micção e",
        "evacuação. A perda impõe o uso de fraldas.",
        "Indica comprometimento neurológico central",
        "avançado ou grave limitação de mobilidade."
      ],
      rec: "Impacto: Dermatites, infecção urinária e isolamento."
    },
    {
      id: 8,
      title: "Alimentar-se (ABVD 4)",
      scale: "Escala de Katz",
      lines: [
        "Capacidade de levar o alimento do prato à boca.",
        "Não envolve preparar a comida, apenas o ato",
        "físico de comer. É a função biológica mais",
        "resistente. Sua perda marca a dependência total."
      ],
      rec: "Impacto: Estágio terminal de declínio funcional."
    }
  ];

  let currentState = 0;
  let selectedStep = null;

  const svg = document.getElementById('bauer-piso05-svg');
  const handle = document.getElementById('bp05-slider-handle');
  const sliderTrack = document.getElementById('bp05-slider-hitbox');

  function getClosestState(x) {
    let closest = 0;
    let minDist = Infinity;
    for (let i = 0; i < tickX.length; i++) {
      let dist = Math.abs(x - tickX[i]);
      if (dist < minDist) {
        minDist = dist;
        closest = i;
      }
    }
    return closest;
  }

  function updateToState(state) {
    currentState = state;
    selectedStep = null;
    renderState();
  }

  function selectStep(id) {
    selectedStep = id;
    renderState();
  }

  function clearStepSelection() {
    selectedStep = null;
    renderState();
  }

  function renderState() {
    const handleX = tickX[currentState];
    handle.setAttribute('cx', handleX);

    const trackWidth = handleX - 170;
    document.getElementById('bp05-slider-active-track').setAttribute('width', trackWidth);
    handle.setAttribute('aria-valuenow', currentState);

    const activeStateData = states[currentState];
    document.getElementById('bp05-slider-status').textContent = 
      `Simulação: ${activeStateData.title}`;

    const declineLine = document.getElementById('bp05-decline-line');
    const linePositions = [40, 115, 185, 255, 325, 395, 465, 535, 655];
    const lineX = linePositions[currentState];
    const lineColor = currentState === 0 ? "var(--c-green)" : (currentState <= 4 ? "var(--c-amber)" : "var(--c-red)");
    declineLine.setAttribute('x1', lineX);
    declineLine.setAttribute('x2', lineX);
    declineLine.setAttribute('stroke', lineColor);

    for (let id = 1; id <= 8; id++) {
      const cardEl = document.getElementById(`bp05-step-card-${id}`);
      const textName = document.getElementById(`bp05-step-name-${id}`);
      const textNum = document.getElementById(`bp05-step-num-${id}`);
      const iconGroup = document.getElementById(`bp05-step-icon-${id}`);
      const groupEl = document.getElementById(`bp05-step-${id}`);

      const isLost = id <= currentState;
      const isSelected = id === selectedStep;

      let strokeColor;
      let cardBg = "var(--card-bg)";
      let opacity = "1.0";

      if (isLost) {
        strokeColor = id <= 4 ? "var(--c-amber)" : "var(--c-red)";
        opacity = "0.55";
      } else {
        strokeColor = "var(--c-green)";
        opacity = "1.0";
      }

      if (isSelected) {
        strokeColor = "var(--c-cyan)";
        cardBg = "rgba(0, 122, 255, 0.08)";
        opacity = "1.0";
      }

      cardEl.setAttribute('stroke', strokeColor);
      cardEl.setAttribute('fill', cardBg);
      groupEl.style.opacity = opacity;

      if (isSelected) {
        textName.setAttribute('fill', "var(--c-cyan)");
        textNum.setAttribute('fill', "var(--c-cyan)");
        if (iconGroup) iconGroup.setAttribute('stroke', "var(--c-cyan)");
      } else {
        textName.setAttribute('fill', "var(--text-primary)");
        textNum.setAttribute('fill', isLost ? strokeColor : "var(--text-muted)");
        if (iconGroup) iconGroup.setAttribute('stroke', isLost ? strokeColor : "var(--text-secondary)");
      }
    }

    const panelTitle = document.getElementById('bp05-panel-title');
    const panelScale = document.getElementById('bp05-panel-scale');
    const panelLine1 = document.getElementById('bp05-panel-line1');
    const panelLine2 = document.getElementById('bp05-panel-line2');
    const panelLine3 = document.getElementById('bp05-panel-line3');
    const panelLine4 = document.getElementById('bp05-panel-line4');
    const panelRec = document.getElementById('bp05-panel-rec');
    const panelScores = document.getElementById('bp05-panel-scores');
    const btnBack = document.getElementById('bp05-btn-back');
    const panelBg = document.getElementById('bp05-panel-bg');

    if (selectedStep !== null) {
      const stepData = steps[selectedStep - 1];
      panelTitle.textContent = stepData.title;
      panelScale.textContent = `${stepData.scale} • Detalhe da Tarefa`;
      panelScale.setAttribute('fill', "var(--c-cyan)");

      panelLine1.textContent = stepData.lines[0];
      panelLine2.textContent = stepData.lines[1];
      panelLine3.textContent = stepData.lines[2];
      panelLine4.textContent = stepData.lines[3];

      panelRec.textContent = stepData.rec;
      panelRec.setAttribute('fill', "var(--c-cyan)");

      panelScores.style.display = 'none';
      btnBack.style.display = 'block';
      panelBg.setAttribute('stroke', 'var(--c-cyan)');
    } else {
      const stageData = states[currentState];
      panelTitle.textContent = stageData.title;
      panelScale.textContent = stageData.scale;
      panelScale.setAttribute('fill', currentState === 0 ? "var(--c-green)" : (currentState <= 4 ? "var(--c-amber)" : "var(--c-red)"));

      panelLine1.textContent = stageData.lines[0];
      panelLine2.textContent = stageData.lines[1];
      panelLine3.textContent = stageData.lines[2];
      panelLine4.textContent = stageData.lines[3];

      panelRec.textContent = stageData.rec;
      panelRec.setAttribute('fill', currentState === 0 ? "var(--c-green)" : (currentState <= 4 ? "var(--c-amber)" : "var(--c-red)"));

      document.getElementById('bp05-badge-lawton-lbl').textContent = `Lawton (AIVD): ${stageData.lawton}`;
      document.getElementById('bp05-badge-lawton-lbl').setAttribute('fill', stageData.lColor);
      document.getElementById('bp05-badge-lawton-bg').setAttribute('fill', stageData.lBg);

      document.getElementById('bp05-badge-katz-lbl').textContent = `Katz (ABVD): ${stageData.katz}`;
      document.getElementById('bp05-badge-katz-lbl').setAttribute('fill', stageData.kColor);
      document.getElementById('bp05-badge-katz-bg').setAttribute('fill', stageData.kBg);

      panelScores.style.display = 'block';
      btnBack.style.display = 'none';
      panelBg.setAttribute('stroke', currentState === 0 ? 'var(--stroke)' : (currentState <= 4 ? 'var(--c-amber)' : 'var(--c-red)'));
    }
  }

  let isDragging = false;

  function getLocalX(evt) {
    const rect = svg.getBoundingClientRect();
    const clientX = evt.touches ? evt.touches[0].clientX : evt.clientX;
    return (clientX - rect.left) * (800 / rect.width);
  }

  function handleInteraction(evt) {
    const x = getLocalX(evt);
    const constrainedX = Math.max(170, Math.min(630, x));
    const state = getClosestState(constrainedX);
    updateToState(state);
  }

  sliderTrack.addEventListener('mousedown', function(evt) {
    isDragging = true;
    handleInteraction(evt);
  });

  window.addEventListener('mousemove', function(evt) {
    if (isDragging) {
      handleInteraction(evt);
    }
  });

  window.addEventListener('mouseup', function() {
    isDragging = false;
  });

  sliderTrack.addEventListener('touchstart', function(evt) {
    isDragging = true;
    handleInteraction(evt);
    evt.preventDefault();
  }, {passive: false});

  window.addEventListener('touchmove', function(evt) {
    if (isDragging) {
      handleInteraction(evt);
      evt.preventDefault();
    }
  }, {passive: false});

  window.addEventListener('touchend', function() {
    isDragging = false;
  });

  for (let id = 1; id <= 8; id++) {
    const groupEl = document.getElementById(`bp05-step-${id}`);
    groupEl.addEventListener('click', function() {
      selectStep(id);
    });
    groupEl.addEventListener('keydown', function(evt) {
      if (evt.key === 'Enter' || evt.key === ' ') {
        evt.preventDefault();
        selectStep(id);
      }
    });
  }

  document.getElementById('bp05-btn-back').addEventListener('click', function(evt) {
    evt.stopPropagation();
    clearStepSelection();
  });

  handle.addEventListener('keydown', function(evt) {
    if (evt.key === 'ArrowRight' || evt.key === 'ArrowUp') {
      evt.preventDefault();
      if (currentState < 8) updateToState(currentState + 1);
    } else if (evt.key === 'ArrowLeft' || evt.key === 'ArrowDown') {
      evt.preventDefault();
      if (currentState > 0) updateToState(currentState - 1);
    }
  });

  renderState();
})();
